type SearchDeparturesRow struct {
	ID                uuid.UUID
	CompanyID         uuid.UUID
	RouteID           uuid.UUID
	DepartureAt       time.Time
	ArrivalEta        time.Time
	BasePrice         int64
	Status            string
	RouteName         string
	IncludedBaggageKg int32
	PricingMode       string
	RoutePrice        int64
	BoardingSeq       int32
	BoardingAt        time.Time
	BoardingStopName  string
	BoardingAgencyID  *uuid.UUID
	BoardingCityID    uuid.UUID
	BoardingCity      string
	AlightingSeq      int32
	AlightingAt       time.Time
	AlightingStopName string
	AlightingCityID   uuid.UUID
	AlightingCity     string
	CompanyName       string
	CompanySlug       string
	BusModel          string
	BusAmenities      []string
	SeatCount         int32
	AvailableSeats    int32
}

// Départs qui desservent la ville de montée puis la ville de descente (n'importe quels arrêts
// de la ligne, pas seulement ses extrémités). Une ligne par agence de montée possible ;
// descente au premier arrêt de la ville d'arrivée. Places libres comptées sur ce tronçon.
// Vente possible tant que le car n'a pas quitté l'arrêt de montée (journal des arrêts),
// et en ligne jusqu'à l'heure prévue à cet arrêt moins le délai de vente.
func (q *Queries) SearchDepartures(ctx context.Context, arg SearchDeparturesParams) ([]SearchDeparturesRow, error) {
	rows, err := q.db.Query(ctx, searchDepartures,
		arg.ToCity,
		arg.FromCity,
		arg.FromTs,
		arg.ToTs,
		arg.CompanyID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchDeparturesRow{}
	for rows.Next() {
		var i SearchDeparturesRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.RouteID,
			&i.DepartureAt,
			&i.ArrivalEta,
			&i.BasePrice,
			&i.Status,
			&i.RouteName,
			&i.IncludedBaggageKg,
			&i.PricingMode,
			&i.RoutePrice,
			&i.BoardingSeq,
			&i.BoardingAt,
			&i.BoardingStopName,
			&i.BoardingAgencyID,
			&i.BoardingCityID,
			&i.BoardingCity,
			&i.AlightingSeq,
			&i.AlightingAt,
			&i.AlightingStopName,
			&i.AlightingCityID,
			&i.AlightingCity,
			&i.CompanyName,
			&i.CompanySlug,
			&i.BusModel,
			&i.BusAmenities,
			&i.SeatCount,
			&i.AvailableSeats,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

